	case "up":
		f.focused = max(f.focused-1, 0)
		f.updateFocus()
		return f, nil
	case "down":
		f.focused = min(f.focused+1, forwardFieldCount-1)
		f.updateFocus()
		return f, nil
	case "esc":
		return f, func() tea.Msg { return ForwardFormCancelMsg{} }
	case "enter":
		return f, f.submit()
	}

